insert overwrite table risk.dwd_risk_ph_uw_bureau_main_baseinfo_df partition(grass_date)
select
cast(get_json_object(header_data,'$.PlatformUserId') as string )  as platform_user_id
,cast(get_json_object(header_data,'$.FlowNo') as string )         as flow_no
,create_time                                                      as request_time
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.IndividualName.FirstName') as string)                                               as first_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.IndividualName.LastName') as string)                                                as last_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.GeneralDataIndividual.GeneralDataIndividual.Gender') as string)                     as gender
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.BirthData.BirthData.Date') as string)                                               as date_of_birth
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.Address[0].Address.FullAddress') as string)                                         as main_full_address
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.Address[0].Address.OccupiedSince') as string)                                       as main_address_occupied_since
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.Address[1].Address.FullAddress') as string)                                         as additional_full_address
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.Address[1].Address.OccupiedSince') as string)                                       as additional_address_occupied_since
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.IdentificationCode.IdentificationCode.Number')                                      as string) as id_number
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.IdentificationCode.IdentificationCodeDesc.TypeDesc') as string)                     as id_typedesc
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.Contact.Contact.Value') as string)                                                  as contact_number
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Subject.Individual.Contact.ContactDesc.TypeDesc') as string)                                           as contact_typedesc
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Application.ContractRequestDate') as string)                                                           as application_contract_request_date
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Application.ContractType') as string)                                                                  as application_contract_type
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Application.Installment.FinancedAmount')     as string)                                                as application_financed_amount
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.EnquiredData.Application.Installment.InstallmentsNumber') as string)                                                as installments_number
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.ApplicationCodes.CBContractCode') as string)                                                                        as cb_contract_code
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.ApplicationCodes.ProviderContractNo') as string)                                                                    as provider_contract_no
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.CBSubjectCode') as string)                                                              as cb_subject_code
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.FlagMatched') as string)                                                                as flag_matched
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.LastUpdateDate')  as string)                                                 as last_update_date
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.GeneralDataIndividual.GeneralDataIndividualDesc.CivilStatusDesc') as string) as civil_status_desc
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.GeneralDataIndividual.GeneralDataIndividualDesc.NationalityDesc') as string) as nationality_desc
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.IndividualName.FormerLastName') as string)                                   as former_last_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.IndividualName.MiddleName') as string)                                       as middle_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.AdditionalNames.FatherFirstName') as string)                                 as father_first_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.AdditionalNames.FatherLastName') as string)                                  as father_last_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.AdditionalNames.FatherMiddleName') as string)                                as father_middle_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.AdditionalNames.MotherMaidenFirstName') as string)                           as mother_maiden_first_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.AdditionalNames.MotherMaidenLastName') as string)                            as mother_maiden_last_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.AdditionalNames.MotherMaidenMiddleName') as string)                          as mother_maiden_middle_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.AdditionalNames.SpouseFirstName') as string)                                 as spouse_first_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.AdditionalNames.SpouseLastName') as string)                                  as spouse_last_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.AdditionalNames.SpouseMiddleName') as string)                                as spouse_middle_name
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.BirthData.BirthData.Place') as string)                                       as place_of_birth
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.EmploymentData.EmploymentData.GrossIncome') as string)                       as gross_income
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.EmploymentData.EmploymentDataDesc.AnnualMonthlyIndicatorDesc') as string)    as gross_income_annual_monthly
,cast(get_json_object(resp_raw_data,'$.SOAPBody.InvokeResponse.Return.Text.Response.Detail.Content.CBOutput.ProductResponse.CBNAEProductOutput.CreditReport.MatchedSubject.Individual.EmploymentData.LastUpdateDate') as string)                                   as gross_income_last_update_date
,grass_date
from risk.ods__credit_risk_datafetch_ph_db__identity_data_history_tab__df
where grass_date = '${grass_date}'
and  data_source_name = 'CrifData'
and data_source_code = 2;